CREATE TABLE sites(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,canonical_host VARCHAR(253) NOT NULL,display_name VARCHAR(100) NOT NULL,include_subdomains BOOLEAN NOT NULL,purpose VARCHAR(16) NOT NULL,access_policy VARCHAR(16) NOT NULL,version BIGINT NOT NULL,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,deleted_at DATETIME(3),UNIQUE(user_id,canonical_host),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE site_feature_policies(site_id BIGINT NOT NULL,feature_code VARCHAR(50) NOT NULL,enabled BOOLEAN NOT NULL,PRIMARY KEY(site_id,feature_code),FOREIGN KEY(site_id) REFERENCES sites(id));
CREATE TABLE content_policies(user_id BIGINT PRIMARY KEY,version BIGINT NOT NULL,payload JSON NOT NULL,updated_at DATETIME(3) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
